import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Navbar.css';

const projectData = {
  "Semiconductor / Micro Electronics": [
    "Aaryans Fab Briefcase",
    "Moscon Product"
  ],
  "Electronics Manufacturing": [
    "PCB Boards",
    "Integrated Circuits (IC)",
